  'ng.rules': 'Règles', 'ng.first': 'Premier (Blancs)', 'ng.second': 'Second (Noirs)',
  'rule.std': '10×10', 'rule.std.d': 'Quatre amazones chacun : les règles standard jouées partout.', 'rule.tagStd': 'Standard',
